// WF-1 init — build the state object per 02 §3
const body = $input.first().json.body || $input.first().json;
const goal = body.goal || body.input || $input.first().json.goal || "reverse this string: hello";
const task_id = `task-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const state = {
  schema_version: 1,
  task_id: task_id,
  goal: String(goal),
  loop: { gate: "test", remaining: 3 },
  recall: { reusable_tools: [], mutation_constraints: [] },
  candidate: null,
  test: { passed: false, runs: [] },
  audit: { security_pass: true, edge_case_pass: true, objections: [] },
  outcome: { status: "", final_answer: "" }
};
// Also derive a simple tool input for the walking skeleton:
// Goal like "reverse this string: hello" → input "hello"
let toolInput = String(goal);
const m = /:\s*"?([^"\n]+)"?\s*$/.exec(toolInput);
if (m) toolInput = m[1].trim();
// stash for downstream
state.test.runs = []; // will be filled by WF-2→WF-5 chain; keep input separately in a transient field
return [{ json: { ...state, _toolInput: toolInput } }];
